head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[content > P > frameMode]<br/>Content 영역이 구성되는 Frame 의 종류를 설정합니다.",
    "validation" : [
        "frameMode='iframe','wframe' 이고 Tabs 의 alwaysDraw 속성이 false 로 적용되면 선택되지 않은 Tab 페이지는 WebSquare XML 페이지를 생성 및 로딩하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onchange"]);

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:tabControl ' + strNameSpace + ' ' + eList + ' alwaysDraw="false" id="" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px" id="tabs2" label="Tabs2"></w2:tabs>';    
    strTarget += '<w2:tabs disabled="false" style="height:40px" id="tabs3" label="Tabs3"></w2:tabs>';    
    strTarget += '<w2:content alwaysDraw="false" style="height:160px;" id="content1">'; 
    strTarget += '<w2:button style="width:80px; width:130px; height:50px;" id="content1_child" label="content1_child"></w2:button>';   
    strTarget += '</w2:content>';
    strTarget += '<w2:content frameMode="iframe" alwaysDraw="false" src="/sample/common_link/tabControl_link_1.xml" style="height:160px" id="content2">';    
    strTarget += '</w2:content>';    
    strTarget += '<w2:content frameMode="iframe" alwaysDraw="false" src="/sample/common_link/tabControl_link_2.xml" style="height:160px" id="content3">';    
    strTarget += '</w2:content>';    
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );

    scwin.btn_getContent_onclick();
}



scwin.btn_getContent_onclick = function (e) {
	let contentBody2 = document.querySelector('[id*=target1_contents_content2_body]');

    if (contentBody2)
        wf_body_bottom.getObj("scwin").setReturnValue("Tabs2 의 content 렌더링 완료");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("Tabs2 의 content 렌더링 미완료");

	let contentBody3 = document.querySelector('[id*=target1_contents_content3_body]');

    if (contentBody3)
        wf_body_bottom.getObj("scwin").setReturnValue("Tabs3 의 content 렌더링 완료");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("Tabs3 의 content 렌더링 미완료");
};



scwin.target1_onchange = function (tabId, index, userTabId) {
    scwin.btn_getContent_onclick();
}



scwin.get_dataList_onclick = function (e) {
    if (target1.isLoaded(1)) {
        let tabWin2 = target1.getWindow(1);

        if (tabWin2 && tabWin2.dataList1) {
            let rowData2 = tabWin2.dataList1.getDataRow(0);
            if (rowData2) {
                wf_body_bottom.getObj("scwin").setReturnValue("content2 의 data : " + rowData2.label);
            }
        }
    }

    if (target1.isLoaded(2)) {
        let tabWin3 = target1.getWindow(2);

        if (tabWin3 && tabWin3.dataList1) {
            let rowData3 = tabWin3.dataList1.getDataRow(0);
            if (rowData3) {
                wf_body_bottom.getObj("scwin").setReturnValue("content3 의 data : " + rowData3.label);
            }
        }
    }
};
